package com.johnny.hotel.group;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.mapper.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.time.*;
@Service@RequiredArgsConstructor public class RoomTypeCapacityGuard{private final RoomTypeMapper types;private final RoomMapper rooms;private final GroupMapper groups;public record Capacity(int physical,int normalBookings,int groupCommitted,int availableForMarket){}
 public Capacity lockAndRead(Long type,LocalDate start,LocalDate end){if(types.selectByIdForUpdate(type)==null)throw new BusinessException("Room type not found");if(start==null||end==null||!start.isBefore(end))throw new BusinessException("Invalid inventory dates");int physical=rooms.sellableCount(type),worstNormal=0,worstGroup=0,min=physical;for(LocalDate d=start;d.isBefore(end);d=d.plusDays(1)){int normal=groups.lockedNormalCommitments(type,d,d.plusDays(1)).size(),held=groups.lockedGroupCommitments(type,d,d.plusDays(1)).stream().mapToInt(Integer::intValue).sum();int available=physical-normal-held;if(available<min){min=available;worstNormal=normal;worstGroup=held;}}return new Capacity(physical,worstNormal,worstGroup,min);}
 public void requireMarketCapacity(Long type,LocalDate start,LocalDate end){if(lockAndRead(type,start,end).availableForMarket()<1)throw new BusinessException("Room type inventory is exhausted");}
 public void requireBlockCapacity(Long type,LocalDate start,LocalDate end,int quantity){if(quantity<1||lockAndRead(type,start,end).availableForMarket()<quantity)throw new BusinessException("Insufficient room type inventory for group block");}}
